// Canvas projection fallback for browsers where WebGL is unavailable.
// Shares the exact same 3D track, geometry and simulation as the GPU renderer.
export class SoftwareRenderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});if(!this.ctx)throw Error('Canvas unavailable');this.backend='canvas';this.resize();this.meshes=[];this.cache=new Map}
 resize(){let d=Math.min(devicePixelRatio||1,1.25);this.canvas.width=Math.round(innerWidth*d);this.canvas.height=Math.round(innerHeight*d);this.w=this.canvas.width;this.h=this.canvas.height}
 load(track,cars){this.track=track;this.cars=cars.map(g=>this.compile(g));for(let c of track.chunks)c.mesh=this.compile(c.geometry,true);this.cache.clear();this.trees=[];let seed=track.id+8,rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let s=0;s<track.length+1200;s+=24)for(let side of[-1,1]){let off=side*(9+rnd()*23),p=track.at(s,off);p.y+=side<0?Math.max(0,(Math.abs(off)-10)*.25):-Math.max(0,(Math.abs(off)-10)*.45);this.trees.push({...p,height:9+rnd()*8})}this.makeTreeSprites(rnd)}
makeTreeSprites(rnd){let base=document.createElement('canvas');base.width=96;base.height=210;let c=base.getContext('2d');c.fillStyle='#343a2c';c.fillRect(45,75,7,134);for(let row=17;row>=0;row--){let y=8+row*10,spread=5+row*1.9;let g=c.createLinearGradient(48-spread,0,48+spread,0);g.addColorStop(0,'#152c24');g.addColorStop(.5,'#294632');g.addColorStop(1,'#1b3227');c.fillStyle=g;c.beginPath();c.moveTo(48,y-20);for(let i=0;i<12;i++){let xx=-spread+i/11*spread*2,yy=y+14-Math.abs(xx)/spread*5+rnd()*6;c.lineTo(48+xx,yy)}c.closePath();c.fill();for(let i=0;i<9;i++){c.fillStyle=rnd()>.5?'#49604455':'#09221955';let x=48+(rnd()*2-1)*spread;c.fillRect(x,y+rnd()*9,1.5,3)}}this.treeSprites=[];for(let i=0;i<12;i++){let cv=document.createElement('canvas');cv.width=96;cv.height=210;let cc=cv.getContext('2d');cc.drawImage(base,0,0);cc.globalCompositeOperation='source-atop';let f=this.track.fog.map(v=>Math.round(v*255));cc.fillStyle=`rgba(${f[0]},${f[1]},${f[2]},${i/12})`;cc.fillRect(0,0,96,210);if(this.track.weather==='rain'){cc.fillStyle='#00132266';cc.fillRect(0,0,96,210)}this.treeSprites.push(cv)}}
 compile(g,scenery=false){let out=[],v=g.v;for(let i=0;i<v.length;i+=27){let col=[v[i+6],v[i+7],v[i+8]];if(scenery&&col[0]<.23&&col[1]<.225&&col[2]<.16)continue;let p={a:[v[i],v[i+1],v[i+2]],b:[v[i+9],v[i+10],v[i+11]],c:[v[i+18],v[i+19],v[i+20]],n:[v[i+3],v[i+4],v[i+5]],col};if(i+53<v.length&&v[i]===v[i+27]&&v[i+1]===v[i+28]&&v[i+2]===v[i+29]&&v[i+18]===v[i+36]&&v[i+19]===v[i+37]&&v[i+20]===v[i+38]&&v[i+6]===v[i+33]){p.d=[v[i+45],v[i+46],v[i+47]];i+=27}out.push(p)}return out}

 sky(c,x,y,w,h){const t=this.track,ctx=this.ctx;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();let night=t.weather==='rain',fog=t.weather==='fog',g=ctx.createLinearGradient(0,y,0,y+h*.65);g.addColorStop(0,night?'#061121':fog?'#849799':'#4c7286');g.addColorStop(.6,night?'#152936':fog?'#9aa9a6':'#b7a99a');g.addColorStop(1,night?'#23343b':fog?'#a8b4ae':'#d8b48c');ctx.fillStyle=g;ctx.fillRect(x,y,w,h);let sunX=x+w*(.76-Math.sin(c.a)*.3),sunY=y+h*.25;if(!fog){let glow=ctx.createRadialGradient(sunX,sunY,1,sunX,sunY,w*.3);glow.addColorStop(0,night?'#b4d5ef24':'#ffcf8f60');glow.addColorStop(1,'#ffffff00');ctx.fillStyle=glow;ctx.fillRect(x,y,w,h*.6);ctx.fillStyle=night?'#c9e3e99c':'#ffe5b9b0';ctx.beginPath();ctx.arc(sunX,sunY,w*(night?.009:.017),0,Math.PI*2);ctx.fill()}
 // Layered mountain silhouettes follow camera yaw for a continuous panorama.
 for(let layer=0;layer<4;layer++){ctx.beginPath();ctx.moveTo(x,y+h*.75);for(let i=0;i<=64;i++){let a=i/64*5+c.a*.7;let ht=.44-Math.abs(Math.sin(a*2.4+layer*1.7))*.13-Math.sin(a*5.2+layer)*.025+layer*.036;ctx.lineTo(x+i/64*w,y+ht*h)}ctx.lineTo(x+w,y+h*.75);ctx.closePath();ctx.fillStyle=night?['#243642','#1d303b','#182c33','#12272d'][layer]:fog?['#859994','#7c938b','#728c80','#688574'][layer]:['#87938b','#70847c','#58746c','#3f635c'][layer];ctx.fill()}ctx.restore()}
 render(c,opponents,mirror){const w=this.w,h=this.h;this.sky(c,0,0,w,h);this.view(c,opponents,0,0,w,h,720);if(mirror&&w/h>1.2){const mw=w*.19,mh=h*.085,mx=(w-mw)/2,my=h*.125,rc={...c,a:c.a+Math.PI,pitch:0};this.ctx.save();this.ctx.beginPath();this.ctx.rect(mx,my,mw,mh);this.ctx.clip();this.sky(rc,mx,my,mw,mh);this.view(rc,opponents,mx,my,mw,mh,240,true);this.ctx.restore()}}
 view(c,cars,ox,oy,w,h,range,rear=false){let ctx=this.ctx,t=this.track,co=Math.cos(c.a),si=Math.sin(c.a),pitch=c.pitch||0,f=h/(2*Math.tan((c.fov||73)*Math.PI/360)),list=[];
 const transform=p=>{let dx=p[0]-c.x,dy=p[1]-c.y,dz=p[2]-c.z,z=dx*si+dz*co;return{x:(dx*co-dz*si),y:dy-pitch*z,z}};
 const clip=vertices=>{let out=[];for(let i=0;i<vertices.length;i++){let a=vertices[i],b=vertices[(i+1)%vertices.length],ia=a.z>.5,ib=b.z>.5;if(ia)out.push(a);if(ia!==ib){let d=(.5-a.z)/(b.z-a.z);out.push({x:a.x+(b.x-a.x)*d,y:a.y+(b.y-a.y)*d,z:.5})}}return out};
 const add=(tri,car)=>{let pts;if(car){let ca=Math.cos(car.a),sa=Math.sin(car.a);pts=[tri.a,tri.b,tri.c,...(tri.d?[tri.d]:[])].map(p=>transform([car.x+p[0]*ca+p[2]*sa,car.y+p[1],car.z-p[0]*sa+p[2]*ca]))}else pts=[tri.a,tri.b,tri.c,...(tri.d?[tri.d]:[])].map(transform);if(pts.every(p=>p.z<.5)||pts.every(p=>p.z>range))return;let avz=pts.reduce((a,p)=>a+p.z,0)/pts.length;if(avz>range)return;pts=clip(pts);if(pts.length<3)return;const screen=pts.map(p=>[ox+w/2+p.x/p.z*f,oy+h/2-p.y/p.z*f]);if(screen.every(p=>p[0]<ox)||screen.every(p=>p[0]>ox+w)||screen.every(p=>p[1]<oy)||screen.every(p=>p[1]>oy+h))return;list.push({screen,z:avz,col:tri.col,n:tri.n,car:!!car})};
 for(let ch of t.chunks){if(ch.end<c.s-(rear?range:60)||ch.s>c.s+(rear?60:range))continue;for(let tri of ch.mesh)add(tri)}
 for(let car of cars){if(Math.abs(car.s-c.s)>range)continue;let p=t.at(car.s,car.x);for(let tri of this.cars[car.mesh])add(tri,{x:p.x,y:p.y,z:p.z,a:p.a+(car.angle||0)})}
 for(let tr of this.trees){if(tr.s<c.s-(rear?range:20)||tr.s>c.s+(rear?20:range))continue;let p=transform([tr.x,tr.y,tr.z]);if(p.z<2||p.z>range)continue;let hh=tr.height/p.z*f,ww=hh*.46,xx=ox+w/2+p.x/p.z*f,yy=oy+h/2-p.y/p.z*f;if(xx+ww<ox||xx-ww>ox+w)continue;list.push({tree:true,x:xx-ww*.5,y:yy-hh,w:ww,h:hh,z:p.z})}list.sort((a,b)=>b.z-a.z);let night=t.weather==='rain';for(let p of list){if(p.tree){let fog=1-Math.exp(-p.z*t.fogDensity);ctx.drawImage(this.treeSprites[Math.min(11,Math.floor(fog*12))],p.x,p.y,p.w,p.h);continue}let sun=Math.max(0,p.n[0]*-.46+p.n[1]*.82+p.n[2]*-.2),lit=.52+sun*.46,head=(night?.9:.12)*Math.exp(-p.z*.025);let fog=1-Math.exp(-p.z*t.fogDensity);let vals=p.col.map((v,i)=>{let col=v*lit*t.light[i]+v*head;if(v>.84&&Math.min(...p.col)<.6)col+=v*(night?.3:0);return Math.round(Math.min(1,col*(1-fog)+t.fog[i]*fog)*255)});ctx.fillStyle=`rgb(${vals[0]},${vals[1]},${vals[2]})`;ctx.beginPath();p.screen.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.65;ctx.stroke();}
 }
}
